  });

  Future<BridgeWriteIntent> prepareLibbookCancelBooking({
    required BridgeLibbookCancelBookingRequest request,
  });

  Future<BridgeWriteIntent> prepareLibbookReserve({
    required BridgeLibbookReserveRequest request,
  });

  /// 准备两条路线的登录页状态。
