  Future<BridgeRoutedSpocAssignments> spocAssignments();

  /// 获取必要的用户资料。
  ///
  /// # Errors
  ///
  /// 客户端已销毁、未认证或 Core 读取资料失败时返回安全错误。
  Future<BridgeRoutedUserProfile> userInfo();

  /// 在线资料保持完整映射，仅持久化遮罩投影；待确认写入禁止隐式恢复。
  ///
  /// # Errors
  /// 保留原读取、身份及退出错误。
  Future<BridgeProfileRefresh> userInfoCached({
    required BridgeOfflineCache cache,
  });

  Future<BridgeRoutedYgdkOverview> ygdkOverview();

  /// 在调用方指定的已认证路线读取阳光打卡概览，不执行 Auto 探测或回退。
  Future<BridgeCallerPinnedYgdkOverview> ygdkOverviewOnRoute({
    required BridgeConnectionMode route,
  });

  Future<BridgeRoutedYgdkRecords> ygdkRecords({
    required int page,
    required int size,
  });

  /// 普通记录查询按实际分类保存；待确认写意图禁止隐式恢复。
  ///
  /// # Errors
  /// 保留原业务及账号/代次错误。
  Future<BridgeYgdkRecordsRefresh> ygdkRecordsCached({
    required BridgeOfflineCache cache,
    required int page,
    required int size,
  });

  /// 概览组合读取要求路线和分类仍匹配，不替代原caller-pinned写后回读。
  ///
  /// # Errors
  /// 上下文变化返回冲突，其他错误沿原读取分类。
  Future<BridgeYgdkRecordsRefresh> ygdkRecordsForOverviewCached({
    required BridgeOfflineCache cache,
    required BridgeConnectionMode route,
    required int classifyId,
    required int page,
    required int size,
  });

  /// 在调用方指定的已认证路线读取阳光打卡记录，不执行 Auto 探测或回退。
  Future<BridgeCallerPinnedYgdkRecords> ygdkRecordsOnRoute({
    required BridgeConnectionMode route,
    required int page,
    required int size,
  });
}

/// 当前连接路线。
enum BridgeConnectionMode { direct, webVpn }

/// Dart 可捕获的 typed 安全错误。
class BridgeError implements FrbException {
  final BridgeErrorCode code;
  final BridgeErrorKind kind;
  final bool retryable;
  final String message;
  final BridgeConnectionMode? resolvedRoute;

  const BridgeError({
    required this.code,
    required this.kind,
    required this.retryable,
    required this.message,
    this.resolvedRoute,
  });

  @override
  int get hashCode =>
      code.hashCode ^
      kind.hashCode ^
      retryable.hashCode ^
      message.hashCode ^
      resolvedRoute.hashCode;

  @override
  bool operator ==(Object other) =>
      identical(this, other) ||
      other is BridgeError &&
          runtimeType == other.runtimeType &&
          code == other.code &&
          kind == other.kind &&
          retryable == other.retryable &&
          message == other.message &&
          resolvedRoute == other.resolvedRoute;
}

/// Core 与 bridge 共用的机器错误码。
enum BridgeErrorCode {
  cacheIdentityMismatch,
  invalidInput,
  authenticationRequired,
  invalidCredentials,
  passwordRiskConfirmationFailed,
  permissionDenied,
  networkError,
  timeout,
  upstreamUnavailable,
  upstreamChanged,
  parseError,
  internalError,
  clientDisposed,
  confirmationRequired,
  intentExpired,
  operationConflict,
  outcomeUnknown,
}

/// bridge 对外的安全错误类别。
enum BridgeErrorKind {
  input,
  authentication,
  network,
  upstream,
  parse,
  internal,
}

